// Global Error Handler - Format Alert (T0: deterministic, no LLM)
// Input: Error Trigger payload. Output: Telegram-ready items ({ text }).
// Dedup: the same error (workflow id + node name + error text without numbers/long ids)
//        is muted for 2 hours; the next alert after the window reports how often it repeated.
// Rate cap: at most 6 alerts per rolling hour; extra alerts are counted, and one
//        "N تنبيهات إضافية مكتومة" message is sent with the next alert once capacity frees.
const SUPPRESS_MS = 2 * 3600000;
const CAP_PER_HOUR = 6;
const HOUR_MS = 3600000;
const KEEP_MS = 24 * 3600000;

function redact(value, max) {
  let s = String(value == null ? '' : value);
  const rules = [
    [/\d{6,12}:[A-Za-z0-9_-]{30,}/g, '[REDACTED_TELEGRAM_TOKEN]'],
    [/\bgithub_pat_[A-Za-z0-9_]{20,}/g, '[REDACTED_GITHUB_TOKEN]'],
    [/\bgh[pousr]_[A-Za-z0-9]{20,}/g, '[REDACTED_GITHUB_TOKEN]'],
    [/\bsk-[A-Za-z0-9_-]{16,}/g, '[REDACTED_API_KEY]'],
    [/\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, '[REDACTED_JWT]'],
    [/\b(bearer|basic)\s+[A-Za-z0-9._~+\/=-]{8,}/gi, '$1 [REDACTED]'],
    [/((?:api[_-]?key|x-n8n-api-key|access[_-]?token|token|secret|password|passwd|authorization)["']?\s*[:=]\s*["']?)(?!\[REDACTED)[^\s"',;&]+/gi, '$1[REDACTED]'],
    [/(\/\/[^\/\s:@]+:)[^@\s\/]+@/g, '$1[REDACTED]@'],
  ];
  for (const r of rules) s = s.replace(r[0], r[1]);
  if (max && s.length > max) s = s.slice(0, max) + '...';
  return s;
}
function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function riyadh(ms) {
  return new Date(ms + 3 * 3600000).toISOString().slice(0, 16).replace('T', ' ') + ' (الرياض)';
}
// Error text without long identifiers (12+ chars containing a digit) and without numbers.
function normalizeError(s) {
  return String(s == null ? '' : s)
    .replace(/(?=[A-Za-z0-9_-]*\d)[A-Za-z0-9_-]{12,}/g, '<id>')
    .replace(/\d+/g, '#')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .slice(0, 300);
}

const state = $getWorkflowStaticData('global');
const now = Date.now();
state.errors = state.errors || {};
state.sent = (state.sent || []).filter(function (t) { return now - t < HOUR_MS; });
state.capMuted = state.capMuted || 0;
for (const k of Object.keys(state.errors)) {
  if (now - state.errors[k].lastSent >= KEEP_MS) delete state.errors[k];
}

const out = [];
for (const item of $input.all()) {
  const d = item.json || {};
  const wf = d.workflow || {};
  const ex = d.execution || {};
  const tr = d.trigger || {};
  const err = ex.error || tr.error || {};
  const message = err.message || err.description || 'خطأ غير معروف';
  const nodeName = ex.lastNodeExecuted || (tr.error && tr.error.node && tr.error.node.name) || '-';
  const key = [wf.id || wf.name || '?', nodeName, normalizeError(message)].join('|');
  const rec = state.errors[key];

  if (rec && now - rec.lastSent < SUPPRESS_MS) { rec.muted = (rec.muted || 0) + 1; continue; }
  if (state.sent.length >= CAP_PER_HOUR) { state.capMuted += 1; continue; }

  if (state.capMuted > 0) {
    out.push({ json: { text: escapeHtml(state.capMuted + ' تنبيهات إضافية مكتومة (السقف ' + CAP_PER_HOUR + ' تنبيهات في الساعة)') } });
    state.capMuted = 0;
  }
  const lines = [
    'فشل مسار',
    '',
    'المسار: ' + (wf.name || 'غير معروف') + (wf.id ? ' (' + wf.id + ')' : ''),
    'التنفيذ: ' + (ex.id ? '#' + ex.id : 'غير متاح (فشل في المُشغِّل)'),
    'العقدة: ' + nodeName,
    'الخطأ: ' + redact(message, 500),
    'الوقت: ' + riyadh(now),
  ];
  if (rec && rec.muted) lines.push('تكرر: ' + rec.muted + ' مرة خلال فترة الكتم السابقة');
  if (ex.mode) lines.push('الوضع: ' + ex.mode);
  if (ex.url) lines.push('الرابط: ' + redact(ex.url));
  state.errors[key] = { lastSent: now, muted: 0 };
  state.sent.push(now);
  out.push({ json: { text: escapeHtml(redact(lines.join('\n'))) } });
}
return out;
